class MLP(Module):
    def __init__(self, nin, widths):
        sizes = [nin] + widths
        self.layers = [
            Layer(sizes[i], sizes[i+1], "identity" if i == len(widths)-1 else "relu")
            for i in range(len(widths))
        ]

